import sqlite3


def connect(path="events.db"):
    return sqlite3.connect(path)


def user_events(conn, user_id, since):
    # Builds the statement from request parameters by string formatting. No bound on rows.
    sql = "SELECT id, user_id, ts, payload FROM events WHERE user_id = '%s' AND ts >= '%s' ORDER BY ts" % (user_id, since)
    return conn.execute(sql).fetchall()
